# B-MRI CoreFocus™ Platform - Installer
# This script will automatically recreate the entire B-MRI CoreFocus™ codebase on your local machine.
# To run this script:
# 1. Open a terminal in an empty directory.
# 2. Run: python install-platform.py
# 3. All files and templates will be generated immediately.

import os

FILES = {'README.md': "# B-MRI CoreFocus™ Platform\n\nThis is the complete custom platform for **B-MRI** that implements the complete **CoreFocus™** client workflow from discovery through dynamic live sessions to final execution blueprint generation.\n\n## Features\n\n1. **Backoffice Console**: Manage clients, view core maps, generate unique questionnaire links.\n2. **CoreHeuristic™ Analytics Engine**: Scans text in incoming questionnaires and auto-extracts focus points (tactical or strategic) along with a confidence score.\n3. **Live Presenter & Vote System**: Run real-time interactive slide sessions (using HTML5 WebSockets) where participants scan a QR code to vote and see live results directly.\n4. **PDF Summary Generator**: Dynamic document creation conforming to professional formatting guidelines with custom ReportLab rules.\n\n## Deployment on Railway\n\n1. Upload this codebase to a private or public GitHub repository.\n2. Link your repository to a new service card in Railway.\n3. Create a domain or CNAME record mapping `app.b-mri.com` to your Railway service's address.\n", 'Procfile': 'web: uvicorn main:app --host 0.0.0.0 --port $PORT', 'railway.json': '{\n  "$schema": "https://railway.app/railway.schema.json",\n  "build": {\n    "builder": "NIXPACKS"\n  },\n  "deploy": {\n    "startCommand": "uvicorn main:app --host 0.0.0.0 --port $PORT",\n    "restartPolicyType": "ON_FAILURE"\n  }\n}', 'requirements.txt': 'fastapi\nuvicorn\njinja2\nreportlab\nwebsockets\n', 'main.py': 'from fastapi import FastAPI, Request, Form, Depends, WebSocket, WebSocketDisconnect\nfrom fastapi.responses import HTMLResponse, RedirectResponse, StreamingResponse\nfrom fastapi.templating import Jinja2Templates\nfrom fastapi.staticfiles import StaticFiles\nimport uvicorn\nimport secrets\nfrom datetime import datetime\nimport json\nimport io\nimport sqlite3\n\n# Import ReportLab for PDF creation\nfrom reportlab.lib.pagesizes import LETTER\nfrom reportlab.lib.colors import HexColor\nfrom reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle\nfrom reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle\nfrom reportlab.lib.enums import TA_CENTER, TA_LEFT, TA_RIGHT, TA_JUSTIFY\n\nfrom database import get_db, init_db\n\napp = FastAPI(title="B-MRI CoreFocus™ Platform")\ntemplates = Jinja2Templates(directory="templates")\n\n# Initialize SQLite database\ninit_db()\n\n# Websocket manager for real-time live presentation\nclass ConnectionManager:\n    def __init__(self):\n        self.active_connections: list[WebSocket] = []\n        self.current_slide = 1\n        self.votes = {}\n\n    async def connect(self, websocket: WebSocket):\n        await websocket.accept()\n        self.active_connections.append(websocket)\n        # Send current state\n        await websocket.send_json({"type": "slide_change", "slide": self.current_slide})\n        await websocket.send_json({"type": "vote_update", "votes": self.votes})\n\n    def disconnect(self, websocket: WebSocket):\n        if websocket in self.active_connections:\n            self.active_connections.remove(websocket)\n\n    async def broadcast(self, message: dict):\n        for connection in self.active_connections:\n            try:\n                await connection.send_json(message)\n            except:\n                pass\n\nmanager = ConnectionManager()\n\n# CoreHeuristic AI Scan Engine\ndef run_core_heuristic(client_id, role, text):\n    # Analyzes inputs and extracts focus points\n    db = get_db()\n    cursor = db.cursor()\n    \n    keywords = {\n        "צוואר בקבוק": ("צוואר בקבוק בתהליכי קבלת החלטות", "נמצא חוסר סנכרון ועיכוב בקבלת החלטות שמוביל לחסימה ארגונית.", "strategic", 4),\n        "רווח": ("מיקוד תמחור ורווחיות לא אופטימלית", "עלה פער ברווחיות וזיהוי מוצרים/שירותים מפסידים.", "strategic", 5),\n        "תפעול": ("קושי סנכרון ממשק מכירות-תפעול", "פער משמעותי בין הבטחת המכירות לבין יכולת המסירה והביצוע של התפעול.", "strategic", 4),\n        "שיווק": ("חוסר מיקוד שיווקי וקהל יעד לא מזוקק", "השאלונים מציפים חוסר בהירות אסטרטגית בניהול הלקוחות והצעת הערך.", "tactical", 3),\n        "עומס": ("עומס ניהולי ועודף משימות טקטיות", "המנהלים מדווחים על קושי בזיקוק העיקר מהטפל בעקבות עומס פניות.", "tactical", 4),\n    }\n\n    found = False\n    for word, (title, desc, f_type, confidence) in keywords.items():\n        if word in text:\n            cursor.execute("""\n                INSERT INTO focus_points (client_id, title, description, type, confidence, source)\n                VALUES (?, ?, ?, ?, ?, ?)\n            """, (client_id, title, f"הודגם מתוך שאלון {role}: \'{text[:100]}...\'", f_type, confidence, f"שאלון {role}"))\n            found = True\n            \n    if not found:\n        # Fallback focus point\n        cursor.execute("""\n            INSERT INTO focus_points (client_id, title, description, type, confidence, source)\n            VALUES (?, ?, ?, ?, ?, ?)\n        """, (client_id, f"נושא דורש בירור - {role}", f"התקבלה תשובה מקיפה: \'{text[:150]}\'", "tactical", 3, f"שאלון {role}"))\n        \n    db.commit()\n    db.close()\n\n\n# Routes\n@app.get("/")\ndef index():\n    return RedirectResponse(url="/dashboard")\n\n@app.get("/dashboard", response_class=HTMLResponse)\ndef dashboard(request: Request):\n    db = get_db()\n    cursor = db.cursor()\n    cursor.execute("SELECT * FROM clients ORDER BY created_at DESC")\n    clients = cursor.fetchall()\n    \n    # Calculate stats\n    cursor.execute("SELECT COUNT(*) FROM questionnaires WHERE status=\'completed\'")\n    total_completed_q = cursor.fetchone()[0]\n    \n    cursor.execute("SELECT COUNT(*) FROM decision_cards")\n    total_decisions = cursor.fetchone()[0]\n    \n    db.close()\n    return templates.TemplateResponse("dashboard.html", {\n        "request": request, \n        "clients": clients,\n        "total_completed_q": total_completed_q,\n        "total_decisions": total_decisions\n    })\n\n@app.post("/client/create")\ndef create_client(name: str = Form(...), industry: str = Form(None)):\n    db = get_db()\n    cursor = db.cursor()\n    cursor.execute("INSERT INTO clients (name, industry, core_map) VALUES (?, ?, ?)", (name, industry, "[]"))\n    client_id = cursor.lastrowid\n    db.commit()\n    db.close()\n    return RedirectResponse(url=f"/client/{client_id}", status_code=303)\n\n@app.get("/client/{client_id}", response_class=HTMLResponse)\ndef client_folder(client_id: int, request: Request):\n    db = get_db()\n    cursor = db.cursor()\n    cursor.execute("SELECT * FROM clients WHERE id=?", (client_id,))\n    client = cursor.fetchone()\n    \n    active_functions = json.loads(client["core_map"]) if client["core_map"] else []\n    \n    # Get Questionnaires\n    cursor.execute("SELECT * FROM questionnaires WHERE client_id=?", (client_id,))\n    questionnaires = cursor.fetchall()\n    \n    # Get Focus Points\n    cursor.execute("SELECT * FROM focus_points WHERE client_id=?", (client_id,))\n    focus_points = cursor.fetchall()\n    \n    # Get Decision Cards\n    cursor.execute("SELECT * FROM decision_cards WHERE client_id=?", (client_id,))\n    decision_cards = cursor.fetchall()\n    \n    db.close()\n    \n    host_url = f"{request.url.scheme}://{request.url.netloc}"\n    \n    return templates.TemplateResponse("client_folder.html", {\n        "request": request,\n        "client": client,\n        "active_functions": active_functions,\n        "questionnaires": questionnaires,\n        "focus_points": focus_points,\n        "decision_cards": decision_cards,\n        "host_url": host_url\n    })\n\n@app.post("/client/{client_id}/update_map")\ndef update_map(client_id: int, functions: list[str] = Form([])):\n    db = get_db()\n    cursor = db.cursor()\n    \n    # Save CoreMap JSON\n    cursor.execute("UPDATE clients SET core_map=? WHERE id=?", (json.dumps(functions), client_id))\n    \n    # Create missing questionnaires\n    for func in functions:\n        cursor.execute("SELECT * FROM questionnaires WHERE client_id=? AND role=?", (client_id, func))\n        if not cursor.fetchone():\n            token = secrets.token_urlsafe(16)\n            cursor.execute("INSERT INTO questionnaires (client_id, token, role) VALUES (?, ?, ?)", (client_id, token, func))\n            \n    db.commit()\n    db.close()\n    return RedirectResponse(url=f"/client/{client_id}", status_code=303)\n\n@app.post("/client/{client_id}/add_focus")\ndef add_focus(client_id: int, title: str = Form(...), type: str = Form(...), confidence: int = Form(...), description: str = Form(...)):\n    db = get_db()\n    cursor = db.cursor()\n    cursor.execute("""\n        INSERT INTO focus_points (client_id, title, description, type, confidence, source)\n        VALUES (?, ?, ?, ?, ?, ?)\n    """, (client_id, title, description, type, confidence, "ידני (יועץ B-MRI)"))\n    db.commit()\n    db.close()\n    return RedirectResponse(url=f"/client/{client_id}", status_code=303)\n\n@app.post("/client/{client_id}/delete_focus/{focus_id}")\ndef delete_focus(client_id: int, focus_id: int):\n    db = get_db()\n    cursor = db.cursor()\n    cursor.execute("DELETE FROM focus_points WHERE id=? AND client_id=?", (focus_id, client_id))\n    db.commit()\n    db.close()\n    return RedirectResponse(url=f"/client/{client_id}", status_code=303)\n\n@app.post("/client/{client_id}/add_decision")\ndef add_decision(client_id: int, title: str = Form(...), outcome: str = Form(...), execution_plan: str = Form(...)):\n    db = get_db()\n    cursor = db.cursor()\n    cursor.execute("""\n        INSERT INTO decision_cards (client_id, title, outcome, execution_plan)\n        VALUES (?, ?, ?, ?)\n    """, (client_id, title, outcome, execution_plan))\n    db.commit()\n    db.close()\n    return RedirectResponse(url=f"/client/{client_id}", status_code=303)\n\n@app.get("/q/{token}", response_class=HTMLResponse)\ndef get_questionnaire(token: str, request: Request):\n    db = get_db()\n    cursor = db.cursor()\n    cursor.execute("SELECT * FROM questionnaires WHERE token=?", (token,))\n    q = cursor.fetchone()\n    db.close()\n    \n    if not q:\n        return HTMLResponse("הקישור אינו בתוקף.", status_code=404)\n        \n    return templates.TemplateResponse("questionnaire.html", {"request": request, "questionnaire": q})\n\n@app.post("/q/{token}/submit")\ndef submit_questionnaire(token: str, q1: str = Form(...), q2: str = Form(...), q3: str = Form(...)):\n    db = get_db()\n    cursor = db.cursor()\n    cursor.execute("SELECT * FROM questionnaires WHERE token=?", (token,))\n    q = cursor.fetchone()\n    \n    if not q:\n        return HTMLResponse("הקישור אינו בתוקף.", status_code=404)\n        \n    responses = {"q1": q1, "q2": q2, "q3": q3}\n    cursor.execute("""\n        UPDATE questionnaires \n        SET status=\'completed\', responses=?, completed_at=?\n        WHERE token=?\n    """, (json.dumps(responses), datetime.now().isoformat(), token))\n    db.commit()\n    \n    # Process with CoreHeuristic engine\n    combined_text = f"{q1} {q2} {q3}"\n    run_core_heuristic(q["client_id"], q["role"], combined_text)\n    \n    db.close()\n    return RedirectResponse(url=f"/q/{token}", status_code=303)\n\n# Live presentation pathways\n@app.get("/live/present", response_class=HTMLResponse)\ndef live_present(request: Request):\n    return templates.TemplateResponse("live_present.html", {"request": request})\n\n@app.get("/live/join", response_class=HTMLResponse)\ndef live_join(request: Request):\n    return templates.TemplateResponse("live_join.html", {"request": request})\n\n@app.get("/live/vote", response_class=HTMLResponse)\ndef live_vote(name: str, role: str, request: Request):\n    return templates.TemplateResponse("live_vote.html", {"request": request, "name": name, "role": role})\n\n# ReportLab PDF Generation\n@app.get("/client/{client_id}/generate_pdf")\ndef generate_pdf(client_id: int):\n    db = get_db()\n    cursor = db.cursor()\n    cursor.execute("SELECT * FROM clients WHERE id=?", (client_id,))\n    client = cursor.fetchone()\n    \n    cursor.execute("SELECT * FROM focus_points WHERE client_id=?", (client_id,))\n    focus_points = cursor.fetchall()\n    \n    cursor.execute("SELECT * FROM decision_cards WHERE client_id=?", (client_id,))\n    decision_cards = cursor.fetchall()\n    db.close()\n\n    # Create a clean binary stream\n    pdf_buffer = io.BytesIO()\n    doc = SimpleDocTemplate(pdf_buffer, pagesize=LETTER, leftMargin=54, rightMargin=54, topMargin=54, bottomMargin=54)\n    story = []\n\n    # Palette\n    COLOR_PRIMARY = HexColor("#1A1A1A")\n    COLOR_BLUE = HexColor("#3A5268")\n    COLOR_RED = HexColor("#E63946")\n    COLOR_GREEN = HexColor("#A8D92E")\n\n    styles = getSampleStyleSheet()\n    \n    # Custom Hebrew supported fonts (using standard fallbacks)\n    title_style = ParagraphStyle(\n        \'Title\',\n        parent=styles[\'Normal\'],\n        fontName=\'Helvetica-Bold\',\n        fontSize=24,\n        textColor=COLOR_PRIMARY,\n        alignment=TA_CENTER,\n        spaceAfter=20\n    )\n    \n    body_style = ParagraphStyle(\n        \'Body\',\n        parent=styles[\'Normal\'],\n        fontName=\'Helvetica\',\n        fontSize=11,\n        textColor=HexColor(\'#333333\'),\n        alignment=TA_RIGHT,\n        spaceAfter=10\n    )\n\n    header_style = ParagraphStyle(\n        \'Header\',\n        parent=styles[\'Normal\'],\n        fontName=\'Helvetica-Bold\',\n        fontSize=14,\n        textColor=COLOR_BLUE,\n        alignment=TA_RIGHT,\n        spaceAfter=12\n    )\n\n    # Document Header\n    story.append(Paragraph("B-MRI | CoreFocus™ Strategic Summary", title_style))\n    story.append(Paragraph(f"חברה / לקוח: {client[\'name\']}", header_style))\n    story.append(Spacer(1, 15))\n\n    story.append(Paragraph("1. מוקדי חסימה והזדמנויות (CoreHeuristic™ Findings)", header_style))\n    for idx, f in enumerate(focus_points):\n        point_text = f"<b>{f[\'title\']}</b> ({f[\'type\']})<br/>{f[\'description\']}"\n        story.append(Paragraph(point_text, body_style))\n        story.append(Spacer(1, 5))\n        \n    story.append(Spacer(1, 15))\n\n    story.append(Paragraph("2. כרטיסי הכרעה ותוכנית עבודה 30/60/90", header_style))\n    for d in decision_cards:\n        decision_text = f"<b>החלטה: {d[\'title\']}</b><br/>תוצאה מצופה: {d[\'outcome\']}<br/>תוכנית פעולה:<br/>{d[\'execution_plan\']}"\n        story.append(Paragraph(decision_text, body_style))\n        story.append(Spacer(1, 10))\n\n    doc.build(story)\n    pdf_buffer.seek(0)\n    \n    return StreamingResponse(pdf_buffer, media_type="application/pdf", headers={\n        "Content-Disposition": f"attachment; filename=bmri-corefocus-{client_id}.pdf"\n    })\n\n# Websocket endpoint for presenter and viewers\n@app.websocket("/ws")\nasync def websocket_endpoint(websocket: WebSocket):\n    await manager.connect(websocket)\n    try:\n        while True:\n            data_str = await websocket.receive_text()\n            data = json.loads(data_str)\n            \n            if data["type"] == "slide_change":\n                manager.current_slide = data["slide"]\n                await manager.broadcast({"type": "slide_change", "slide": manager.current_slide})\n                \n            elif data["type"] == "submit_vote":\n                option = data["option"]\n                manager.votes[option] = manager.votes.get(option, 0) + 1\n                await manager.broadcast({"type": "vote_update", "votes": manager.votes})\n    except WebSocketDisconnect:\n        manager.disconnect(websocket)\n\nif __name__ == "__main__":\n    uvicorn.run("main:app", host="0.0.0.0", port=4000, reload=True)\n', 'database.py': 'import sqlite3\nimport json\nimport os\n\nDB_PATH = "bmri_corefocus.db"\n\ndef get_db():\n    conn = sqlite3.connect(DB_PATH)\n    conn.row_factory = sqlite3.Row\n    return conn\n\ndef init_db():\n    conn = get_db()\n    cursor = conn.cursor()\n    \n    # Clients Table\n    cursor.execute("""\n    CREATE TABLE IF NOT EXISTS clients (\n        id INTEGER PRIMARY KEY AUTOINCREMENT,\n        name TEXT NOT NULL,\n        industry TEXT,\n        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n        core_map TEXT\n    )\n    """)\n    \n    # Questionnaires Table\n    cursor.execute("""\n    CREATE TABLE IF NOT EXISTS questionnaires (\n        id INTEGER PRIMARY KEY AUTOINCREMENT,\n        client_id INTEGER,\n        token TEXT UNIQUE,\n        role TEXT,\n        status TEXT DEFAULT \'pending\',\n        responses TEXT,\n        completed_at TIMESTAMP,\n        FOREIGN KEY (client_id) REFERENCES clients(id)\n    )\n    """)\n    \n    # Focus Points Table\n    cursor.execute("""\n    CREATE TABLE IF NOT EXISTS focus_points (\n        id INTEGER PRIMARY KEY AUTOINCREMENT,\n        client_id INTEGER,\n        title TEXT,\n        description TEXT,\n        type TEXT, -- tactical / strategic\n        confidence INTEGER, -- 1 to 5\n        source TEXT,\n        status TEXT DEFAULT \'suggested\', -- suggested / approved\n        score REAL DEFAULT 0.0,\n        FOREIGN KEY (client_id) REFERENCES clients(id)\n    )\n    """)\n    \n    # Decision Cards Table\n    cursor.execute("""\n    CREATE TABLE IF NOT EXISTS decision_cards (\n        id INTEGER PRIMARY KEY AUTOINCREMENT,\n        client_id INTEGER,\n        focus_point_id INTEGER,\n        title TEXT,\n        alternatives TEXT, -- JSON list of alternatives\n        outcome TEXT,\n        context TEXT,\n        evidence TEXT,\n        dependencies TEXT,\n        objections TEXT,\n        resources TEXT,\n        final_decision TEXT,\n        execution_plan TEXT, -- JSON for 30/60/90\n        FOREIGN KEY (client_id) REFERENCES clients(id),\n        FOREIGN KEY (focus_point_id) REFERENCES focus_points(id)\n    )\n    """)\n    \n    # Live Sessions Table\n    cursor.execute("""\n    CREATE TABLE IF NOT EXISTS live_sessions (\n        id INTEGER PRIMARY KEY AUTOINCREMENT,\n        client_id INTEGER,\n        current_slide INTEGER DEFAULT 1,\n        active_votes TEXT, -- JSON representation of votes\n        is_active BOOLEAN DEFAULT 0,\n        FOREIGN KEY (client_id) REFERENCES clients(id)\n    )\n    """)\n    \n    conn.commit()\n    conn.close()\n\nif __name__ == "__main__":\n    init_db()\n', 'templates/live_vote.html': '<!DOCTYPE html>\n<html lang="he" dir="rtl">\n<head>\n    <meta charset="UTF-8">\n    <meta name="viewport" content="width=device-width, initial-scale=1.0">\n    <title>שלט הצבעה - B-MRI CoreFocus™</title>\n    <script src="https://cdn.tailwindcss.com"></script>\n    <script>\n        tailwind.config = {\n            theme: {\n                extend: {\n                    colors: {\n                        brandDark: \'#1A1A1A\',\n                        brandBlue: \'#3A5268\',\n                        brandRed: \'#E63946\',\n                        brandGreen: \'#A8D92E\',\n                    }\n                }\n            }\n        }\n    </script>\n    <style>\n        body {\n            background-color: #1A1A1A;\n            color: #F8FAFC;\n        }\n    </style>\n</head>\n<body class="font-sans flex flex-col justify-between h-screen p-6">\n    <!-- Top Header -->\n    <header class="text-center">\n        <h1 class="text-lg font-bold text-white">B-MRI שלט סנכרון</h1>\n        <p class="text-xs text-slate-400 mt-0.5">שלום, <span class="text-brandGreen font-bold">{{ name }}</span> ({{ role }})</p>\n    </header>\n\n    <!-- Dynamic Voting Screen -->\n    <main class="flex-grow flex items-center justify-center my-6">\n        <!-- Interactive Slide 3: CoreMap Voting -->\n        <div id="vote-screen-3" class="hidden flex-col items-center gap-4 w-full">\n            <h2 class="text-base font-bold text-slate-200 text-center">בחר את הפונקציה בעלת ה"רעש" הניהולי הגבוה ביותר כעת:</h2>\n            <div class="grid grid-cols-2 gap-3 w-full">\n                {% for label in ["הנהלה", "שיווק", "מכירות", "תפעול", "כספים", "משאבי אנוש", "טכנולוגיה", "שירות לקוחות"] %}\n                <button onclick="submitVote(\'{{ label }}\')" id="btn-{{ label }}" class="bg-brandDark border border-brandBlue/25 hover:border-brandRed py-3 px-2 rounded-xl text-xs font-semibold text-slate-300 transition">\n                    {{ label }}\n                </button>\n                {% endfor %}\n            </div>\n            <p class="text-[10px] text-slate-500 mt-2">הקש על פונקציה כדי להצביע. תוכל לשנות הצבעה בכל עת.</p>\n        </div>\n\n        <!-- Standby Screen (for other slides) -->\n        <div id="standby-screen" class="flex flex-col items-center justify-center text-center gap-4 max-w-xs">\n            <span class="text-4xl animate-pulse">⏳</span>\n            <h2 class="text-base font-bold text-white">ממתין למנחה הספרינט...</h2>\n            <p class="text-xs text-slate-400">השלט שלך מסונכרן. המסך יתחלף אוטומטית ברגע שהמנחה יעבור לשקף אינטראקטיבי.</p>\n        </div>\n    </main>\n\n    <!-- Brand Signature -->\n    <footer class="text-center text-[10px] text-slate-600">\n        לזהות • לזקק • להכריע. B-MRI CoreFocus™\n    </footer>\n\n    <script>\n        const host = window.location.host;\n        const protocol = window.location.protocol === \'https:\' ? \'wss:\' : \'ws:\';\n        let ws;\n        let selectedVote = null;\n\n        function connectWS() {\n            ws = new WebSocket(`${protocol}//${host}/ws`);\n            ws.onmessage = (event) => {\n                const data = JSON.parse(event.data);\n                if (data.type === \'slide_change\') {\n                    handleSlideChange(data.slide);\n                }\n            };\n            ws.onclose = () => {\n                setTimeout(connectWS, 2000);\n            };\n        }\n\n        function handleSlideChange(slideIdx) {\n            // Currently slide 3 is our main voting slide\n            if (slideIdx === 3) {\n                document.getElementById(\'vote-screen-3\').classList.remove(\'hidden\');\n                document.getElementById(\'vote-screen-3\').classList.add(\'flex\');\n                document.getElementById(\'standby-screen\').classList.add(\'hidden\');\n                document.getElementById(\'standby-screen\').classList.remove(\'flex\');\n            } else {\n                document.getElementById(\'vote-screen-3\').classList.add(\'hidden\');\n                document.getElementById(\'vote-screen-3\').classList.remove(\'flex\');\n                document.getElementById(\'standby-screen\').classList.remove(\'hidden\');\n                document.getElementById(\'standby-screen\').classList.add(\'flex\');\n            }\n        }\n\n        function submitVote(option) {\n            // Highlight button\n            const labels = ["הנהלה", "שיווק", "מכירות", "תפעול", "כספים", "משאבי אנוש", "טכנולוגיה", "שירות לקוחות"];\n            labels.forEach(label => {\n                document.getElementById(`btn-${label}`).classList.remove(\'border-brandRed\', \'text-brandRed\', \'bg-brandRed/5\');\n                document.getElementById(`btn-${label}`).classList.add(\'border-brandBlue/25\', \'text-slate-300\');\n            });\n\n            document.getElementById(`btn-${option}`).classList.remove(\'border-brandBlue/25\', \'text-slate-300\');\n            document.getElementById(`btn-${option}`).classList.add(\'border-brandRed\', \'text-brandRed\', \'bg-brandRed/5\');\n\n            selectedVote = option;\n\n            if (ws && ws.readyState === WebSocket.OPEN) {\n                ws.send(JSON.stringify({\n                    type: \'submit_vote\',\n                    option: option,\n                    user: "{{ name }}"\n                }));\n            }\n        }\n\n        connectWS();\n    </script>\n</body>\n</html>', 'templates/live_join.html': '<!DOCTYPE html>\n<html lang="he" dir="rtl">\n<head>\n    <meta charset="UTF-8">\n    <meta name="viewport" content="width=device-width, initial-scale=1.0">\n    <title>התחברות לספרינט Live - B-MRI</title>\n    <script src="https://cdn.tailwindcss.com"></script>\n    <script>\n        tailwind.config = {\n            theme: {\n                extend: {\n                    colors: {\n                        brandDark: \'#1A1A1A\',\n                        brandBlue: \'#3A5268\',\n                        brandRed: \'#E63946\',\n                        brandGreen: \'#A8D92E\',\n                    }\n                }\n            }\n        }\n    </script>\n    <style>\n        body {\n            background-color: #1A1A1A;\n            color: #F8FAFC;\n        }\n    </style>\n</head>\n<body class="font-sans flex flex-col justify-center items-center min-h-screen px-4">\n    <div class="max-w-md w-full bg-black/30 border border-brandBlue/30 p-8 rounded-2xl shadow-2xl">\n        <div class="text-center mb-6">\n            <h1 class="text-2xl font-bold text-white">כניסה למערכת הצבעה</h1>\n            <p class="text-slate-400 mt-1 text-sm">הזן את פרטיך כדי להתחבר ישירות למצגת הספרינט של B-MRI</p>\n        </div>\n\n        <form action="/live/vote" method="GET" class="flex flex-col gap-4">\n            <div>\n                <label class="block text-slate-300 text-xs mb-1">שם מלא</label>\n                <input type="text" name="name" required placeholder="ישראל ישראלי" class="w-full bg-brandDark border border-brandBlue/30 rounded px-3 py-2 text-white focus:outline-none focus:border-brandRed">\n            </div>\n            <div>\n                <label class="block text-slate-300 text-xs mb-1">תפקיד / פונקציה בארגון</label>\n                <select name="role" class="w-full bg-brandDark border border-brandBlue/30 rounded px-3 py-2 text-white focus:outline-none">\n                    <option value="הנהלה">מנכ"ל / הנהלה בכירה</option>\n                    <option value="שיווק">מנהל שיווק</option>\n                    <option value="מכירות">מנהל מכירות</option>\n                    <option value="תפעול">מנהל תפעול</option>\n                    <option value="כספים">מנהל כספים</option>\n                    <option value="משאבי אנוש">משאבי אנוש</option>\n                </select>\n            </div>\n            <button type="submit" class="bg-brandRed hover:bg-brandRed/90 text-white font-semibold py-2.5 rounded transition mt-2">התחבר וסנכרן שלט 📱</button>\n        </form>\n    </div>\n</body>\n</html>', 'templates/live_present.html': '<!DOCTYPE html>\n<html lang="he" dir="rtl">\n<head>\n    <meta charset="UTF-8">\n    <meta name="viewport" content="width=device-width, initial-scale=1.0">\n    <title>מצגת ספרינט Live - B-MRI</title>\n    <script src="https://cdn.tailwindcss.com"></script>\n    <script>\n        tailwind.config = {\n            theme: {\n                extend: {\n                    colors: {\n                        brandDark: \'#111111\',\n                        brandBlue: \'#3A5268\',\n                        brandRed: \'#E63946\',\n                        brandGreen: \'#A8D92E\',\n                    }\n                }\n            }\n        }\n    </script>\n    <style>\n        body {\n            background-color: #111111;\n            color: #F8FAFC;\n            overflow: hidden;\n        }\n        .slide {\n            display: none;\n            height: 100vh;\n        }\n        .slide.active {\n            display: flex;\n        }\n    </style>\n</head>\n<body class="font-sans flex flex-col justify-between h-screen">\n    <!-- Navbar / Chrome -->\n    <header class="bg-black/40 border-b border-brandBlue/20 px-8 py-4 flex justify-between items-center">\n        <div class="flex items-center gap-3">\n            <div class="flex items-center gap-1.5">\n                <span class="w-2.5 h-2.5 rounded-full bg-brandRed"></span>\n                <span class="w-8 h-[2px] bg-brandBlue"></span>\n                <span class="w-2.5 h-2.5 rounded-full bg-brandGreen"></span>\n            </div>\n            <span class="text-lg font-bold tracking-wider text-white">B-MRI CoreFocus™ Sprint</span>\n        </div>\n        <div class="bg-brandDark border border-brandBlue/30 px-4 py-1.5 rounded-full text-xs text-slate-400">\n            התחברות משתתפים: <span class="text-brandGreen font-bold" id="join-url"></span>\n        </div>\n    </header>\n\n    <!-- Slides Container -->\n    <div class="flex-grow flex items-center justify-center p-8">\n        <!-- Slide 1: Title -->\n        <div id="slide-1" class="slide active flex-col items-center justify-center text-center gap-6">\n            <h1 class="text-5xl font-extrabold text-white leading-tight">CoreFocus™ Sprint</h1>\n            <p class="text-2xl text-brandBlue font-medium">מעבר מ"רעש" ארגוני ל-1–3 החלטות ליבה לביצוע</p>\n            <div class="flex items-center gap-2 mt-4 text-slate-500 text-sm">\n                <span>אריאל בן-עמי</span>\n                <span>•</span>\n                <span>אלי כהן</span>\n            </div>\n        </div>\n\n        <!-- Slide 2: Challenge -->\n        <div id="slide-2" class="slide flex-col items-center justify-center text-center gap-6 max-w-4xl">\n            <h2 class="text-3xl font-bold text-white">האתגר הניהולי: עומס, אי-ודאות ועיכובים</h2>\n            <div class="grid grid-cols-1 md:grid-cols-2 gap-8 mt-6">\n                <div class="bg-brandDark border border-brandBlue/10 p-8 rounded-xl flex flex-col justify-center">\n                    <span class="text-6xl font-extrabold text-brandRed">70%-80%</span>\n                    <p class="text-slate-300 mt-3 text-sm">מהמנהלים מעידים על עיכוב בקבלת החלטות אסטרטגיות ועל קושי בזיקוק העיקר מהטפל</p>\n                </div>\n                <div class="bg-brandDark border border-brandBlue/10 p-8 rounded-xl flex flex-col justify-center">\n                    <span class="text-6xl font-extrabold text-brandRed">21%</span>\n                    <p class="text-slate-300 mt-3 text-sm">בלבד מהמנהלים דיווחו שהאסטרטגיות שלהם עברו את מבחני האסטרטגיה המעשיים (מקינזי)</p>\n                </div>\n            </div>\n        </div>\n\n        <!-- Slide 3: CoreMap (Interactive Voting) -->\n        <div id="slide-3" class="slide flex-col items-center justify-center text-center gap-4 w-full max-w-5xl">\n            <h2 class="text-3xl font-bold text-white">CoreMap™ — איפה עוצמת ה"רעש" אצלכם?</h2>\n            <p class="text-slate-400 text-sm mb-4">המנהלים מתבקשים להצביע כעת במכשירי הנייד שלהם</p>\n            \n            <div class="grid grid-cols-2 sm:grid-cols-4 gap-4 w-full">\n                {% for label in ["הנהלה", "שיווק", "מכירות", "תפעול", "כספים", "משאבי אנוש", "טכנולוגיה", "שירות לקוחות"] %}\n                <div class="bg-brandDark border border-brandBlue/20 p-4 rounded-xl flex flex-col justify-between h-32 relative overflow-hidden">\n                    <span class="text-sm font-bold text-slate-300 z-10">{{ label }}</span>\n                    <span class="text-3xl font-extrabold text-brandRed z-10" id="count-{{ label }}">0</span>\n                    <div class="absolute bottom-0 left-0 right-0 bg-brandRed/10 transition-all duration-500" style="height: 0%" id="bar-{{ label }}"></div>\n                </div>\n                {% endfor %}\n            </div>\n        </div>\n\n        <!-- Slide 4: 3 Decisions -->\n        <div id="slide-4" class="slide flex-col items-center justify-center text-center gap-6 max-w-3xl">\n            <h2 class="text-4xl font-extrabold text-brandRed">3 ההחלטות שעל השולחן</h2>\n            <p class="text-xl text-slate-300 leading-relaxed mt-4">\n                "אילו 3 החלטות ליבה מעסיקות אותך כיום וטרם הוכרעו? מה מונע מהן להפוך לביצוע? ומהו המחיר של אי-הכרעה עבור הארגון כיום?"\n            </p>\n        </div>\n\n        <!-- Slide 5: The Engine comparison -->\n        <div id="slide-5" class="slide flex-col items-center justify-center text-center gap-6 w-full max-w-4xl">\n            <h2 class="text-3xl font-bold text-white">המנוע של B-MRI לעומת ייעוץ מסורתי</h2>\n            <div class="grid grid-cols-1 md:grid-cols-2 gap-8 w-full mt-6">\n                <div class="bg-brandDark border border-brandBlue/15 p-6 rounded-xl text-right">\n                    <h3 class="text-lg font-bold text-slate-400 border-b border-brandBlue/10 pb-2 mb-4">ייעוץ מסורתי</h3>\n                    <ul class="text-xs text-slate-400 flex flex-col gap-3">\n                        <li>• תהליכים ארוכים של חודשים</li>\n                        <li>• מאות שקפים ומצגות תיאורטיות</li>\n                        <li>• אובדן מומנטום ניהולי בארגון</li>\n                    </ul>\n                </div>\n                <div class="bg-brandDark border border-brandRed/30 p-6 rounded-xl text-right">\n                    <h3 class="text-lg font-bold text-brandRed border-b border-brandRed/20 pb-2 mb-4">CoreFocus™ Sprint</h3>\n                    <ul class="text-xs text-slate-200 flex flex-col gap-3">\n                        <li>• ספרינט ממוקד וקצר (עד שבועיים)</li>\n                        <li>• זיקוק שיטתי ל-1-3 מהלכי ליבה</li>\n                        <li>• תוכנית ביצוע 30/60/90 מוכנה מייד</li>\n                    </ul>\n                </div>\n            </div>\n        </div>\n\n        <!-- Slide 6: Execution Roadmap -->\n        <div id="slide-6" class="slide flex-col items-center justify-center text-center gap-6 max-w-2xl">\n            <h2 class="text-3xl font-bold text-white">תוצרים מוחשיים ומהדיים</h2>\n            <div class="flex flex-col gap-4 text-right w-full mt-6">\n                <div class="bg-brandDark border border-brandBlue/20 p-4 rounded-lg flex items-center gap-4">\n                    <span class="text-2xl">🎯</span>\n                    <div>\n                        <h4 class="font-bold text-white">בהירות אסטרטגית</h4>\n                        <p class="text-xs text-slate-400 mt-0.5">מיפוי מדויק של חסימות והזדמנויות</p>\n                    </div>\n                </div>\n                <div class="bg-brandDark border border-brandBlue/20 p-4 rounded-lg flex items-center gap-4">\n                    <span class="text-2xl">📈</span>\n                    <div>\n                        <h4 class="font-bold text-white">תעדוף ממוקד</h4>\n                        <p class="text-xs text-slate-400 mt-0.5">מנוע שקלול ממוחשב שמנקה רעשים</p>\n                    </div>\n                </div>\n                <div class="bg-brandDark border border-brandBlue/20 p-4 rounded-lg flex items-center gap-4">\n                    <span class="text-2xl">✅</span>\n                    <div>\n                        <h4 class="font-bold text-white">ביטחון ניהולי וביצוע</h4>\n                        <p class="text-xs text-slate-400 mt-0.5">תוכנית 30/60/90 שלמה ללא מצגות שווא</p>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </div>\n\n    <!-- Controls / Footer -->\n    <footer class="bg-black/60 border-t border-brandBlue/20 px-8 py-4 flex justify-between items-center">\n        <button onclick="prevSlide()" class="bg-brandBlue hover:bg-brandBlue/80 text-white text-xs px-4 py-2 rounded transition">← הקודם</button>\n        <div class="text-xs text-slate-500">שקף <span id="slide-num">1</span> מתוך 6</div>\n        <button onclick="nextSlide()" class="bg-brandRed hover:bg-brandRed/90 text-white text-xs px-4 py-2 rounded transition">הבא ←</button>\n    </footer>\n\n    <script>\n        let currentSlideIdx = 1;\n        const totalSlides = 6;\n        let ws;\n\n        // Auto-detect host URL\n        const host = window.location.host;\n        const protocol = window.location.protocol === \'https:\' ? \'wss:\' : \'ws:\';\n        document.getElementById(\'join-url\').innerText = window.location.origin + "/live/join";\n\n        function connectWS() {\n            ws = new WebSocket(`${protocol}//${host}/ws`);\n            ws.onmessage = (event) => {\n                const data = JSON.parse(event.data);\n                if (data.type === \'vote_update\') {\n                    updateVotesDisplay(data.votes);\n                }\n            };\n            ws.onclose = () => {\n                setTimeout(connectWS, 2000);\n            };\n        }\n\n        function updateVotesDisplay(votes) {\n            // Reset counts\n            const labels = ["הנהלה", "שיווק", "מכירות", "תפעול", "כספים", "משאבי אנוש", "טכנולוגיה", "שירות לקוחות"];\n            labels.forEach(label => {\n                document.getElementById(`count-${label}`).innerText = \'0\';\n                document.getElementById(`bar-${label}`).style.height = \'0%\';\n            });\n\n            // Calculate total votes\n            let total = 0;\n            for (let v in votes) {\n                total += votes[v];\n            }\n\n            // Update\n            for (let v in votes) {\n                if (document.getElementById(`count-${v}`)) {\n                    document.getElementById(`count-${v}`).innerText = votes[v];\n                    if (total > 0) {\n                        const pct = (votes[v] / total) * 100;\n                        document.getElementById(`bar-${v}`).style.height = `${pct}%`;\n                    }\n                }\n            }\n        }\n\n        function showSlide(idx) {\n            document.querySelectorAll(\'.slide\').forEach(s => s.classList.remove(\'active\'));\n            document.getElementById(`slide-${idx}`).classList.add(\'active\');\n            document.getElementById(\'slide-num\').innerText = idx;\n            currentSlideIdx = idx;\n\n            // Broadcast slide change over WebSocket\n            if (ws && ws.readyState === WebSocket.OPEN) {\n                ws.send(JSON.stringify({ type: \'slide_change\', slide: idx }));\n            }\n        }\n\n        function nextSlide() {\n            if (currentSlideIdx < totalSlides) {\n                showSlide(currentSlideIdx + 1);\n            }\n        }\n\n        function prevSlide() {\n            if (currentSlideIdx > 1) {\n                showSlide(currentSlideIdx - 1);\n            }\n        }\n\n        connectWS();\n    </script>\n</body>\n</html>', 'templates/questionnaire.html': '<!DOCTYPE html>\n<html lang="he" dir="rtl">\n<head>\n    <meta charset="UTF-8">\n    <meta name="viewport" content="width=device-width, initial-scale=1.0">\n    <title>שאלון אבחון Pulse - B-MRI</title>\n    <script src="https://cdn.tailwindcss.com"></script>\n    <script>\n        tailwind.config = {\n            theme: {\n                extend: {\n                    colors: {\n                        brandDark: \'#1A1A1A\',\n                        brandBlue: \'#3A5268\',\n                        brandRed: \'#E63946\',\n                        brandGreen: \'#A8D92E\',\n                    }\n                }\n            }\n        }\n    </script>\n    <style>\n        body {\n            background-color: #1A1A1A;\n            color: #F8FAFC;\n        }\n    </style>\n</head>\n<body class="font-sans flex flex-col min-h-screen py-8 px-4 justify-center items-center">\n    <div class="max-w-xl w-full bg-black/30 border border-brandBlue/30 p-8 rounded-2xl shadow-2xl">\n        <div class="text-center mb-6">\n            <div class="flex justify-center items-center gap-1.5 mb-2">\n                <span class="w-2.5 h-2.5 rounded-full bg-brandRed"></span>\n                <span class="w-8 h-[2px] bg-brandBlue"></span>\n                <span class="w-2.5 h-2.5 rounded-full bg-brandGreen"></span>\n            </div>\n            <h1 class="text-2xl font-bold text-white">אבחון Pulse דיגיטלי</h1>\n            <p class="text-slate-400 mt-1 text-sm">פונקציה: <span class="text-brandGreen font-semibold">{{ questionnaire.role }}</span></p>\n        </div>\n\n        {% if questionnaire.status == \'completed\' %}\n        <div class="text-center py-8">\n            <span class="text-5xl">✅</span>\n            <h2 class="text-xl font-bold text-white mt-4">השאלון הושלם בהצלחה!</h2>\n            <p class="text-slate-400 mt-2">תשובותיך נקלטו במערכת B-MRI ויסייעו במיקוד מהלכי הליבה.</p>\n        </div>\n        {% else %}\n        <form action="/q/{{ questionnaire.token }}/submit" method="POST" class="flex flex-col gap-6">\n            <div>\n                <label class="block text-slate-300 text-sm font-semibold mb-2">1. מהו האתגר או צוואר הבקבוק המרכזי המעכב כיום את פונקציית {{ questionnaire.role }} בארגון?</label>\n                <textarea name="q1" required class="w-full bg-brandDark border border-brandBlue/30 rounded-lg p-3 text-white text-sm focus:outline-none focus:border-brandRed h-24" placeholder="תאר את הבעיה בפירוט..."></textarea>\n            </div>\n            <div>\n                <label class="block text-slate-300 text-sm font-semibold mb-2">2. אילו שלוש החלטות ליבה מעסיקות אותך כיום וטרם הוכרעו?</label>\n                <textarea name="q2" required class="w-full bg-brandDark border border-brandBlue/30 rounded-lg p-3 text-white text-sm focus:outline-none focus:border-brandRed h-24" placeholder="1. ... \n2. ... \n3. ..."></textarea>\n            </div>\n            <div>\n                <label class="block text-slate-300 text-sm font-semibold mb-2">3. מהו המחיר שהארגון משלם כרגע על היעדר ההכרעה בנושאים אלו?</label>\n                <textarea name="q3" required class="w-full bg-brandDark border border-brandBlue/30 rounded-lg p-3 text-white text-sm focus:outline-none focus:border-brandRed h-24" placeholder="השפעה על רווחיות, צמיחה, משאבים וכו\'"></textarea>\n            </div>\n            <button type="submit" class="bg-brandRed hover:bg-brandRed/90 text-white font-semibold py-3 rounded-lg transition shadow-lg mt-2">שלח תשובות אבחון ←</button>\n        </form>\n        {% endif %}\n    </div>\n</body>\n</html>', 'templates/client_folder.html': '{% extends "base.html" %}\n\n{% block title %}תיק לקוח - {{ client.name }}{% endblock %}\n\n{% block content %}\n<div class="flex flex-col gap-8">\n    <!-- Header -->\n    <div class="flex justify-between items-start">\n        <div>\n            <a href="/dashboard" class="text-brandBlue hover:text-brandGreen text-sm mb-2 inline-block">← חזרה ללוח הבקרה</a>\n            <h1 class="text-3xl font-bold text-white">{{ client.name }}</h1>\n            <p class="text-slate-400 mt-1">מגזר: {{ client.industry }} | תאריך פתיחה: {{ client.created_at[:10] }}</p>\n        </div>\n        <div class="flex gap-3">\n            <a href="/client/{{ client.id }}/generate_pdf" class="bg-brandGreen hover:bg-brandGreen/90 text-black font-semibold px-5 py-2.5 rounded-lg transition shadow-lg">\n                הורד דוח סיכום PDF 📄\n            </a>\n        </div>\n    </div>\n\n    <div class="grid grid-cols-1 lg:grid-cols-3 gap-8">\n        <!-- CoreMap & Questionnaires -->\n        <div class="lg:col-span-2 flex flex-col gap-8">\n            <!-- CoreMap Selection -->\n            <div class="bg-black/30 border border-brandBlue/20 p-6 rounded-xl">\n                <h2 class="text-xl font-bold text-white mb-4 flex items-center gap-2">\n                    <span class="w-2.5 h-2.5 rounded-full bg-brandRed"></span> CoreMap™ mapping\n                </h2>\n                <p class="text-slate-400 text-sm mb-4">בחר את הפונקציות המרכזיות בארגון שייכללו באבחון. המערכת תייצר עבורן שאלונים ייעודיים באופן אוטומטי.</p>\n                \n                <form action="/client/{{ client.id }}/update_map" method="POST">\n                    <div class="grid grid-cols-2 sm:grid-cols-3 gap-3 mb-4">\n                        {% for func in ["הנהלה", "שיווק", "מכירות", "תפעול", "כספים", "משאבי אנוש", "טכנולוגיה", "שירות לקוחות"] %}\n                        <label class="flex items-center gap-2 p-3 bg-brandDark border border-brandBlue/10 hover:border-brandBlue/40 rounded-lg cursor-pointer transition">\n                            <input type="checkbox" name="functions" value="{{ func }}" {% if func in active_functions %}checked{% endif %} class="accent-brandRed">\n                            <span class="text-sm font-medium text-slate-200">{{ func }}</span>\n                        </label>\n                        {% endfor %}\n                    </div>\n                    <button type="submit" class="bg-brandBlue text-white hover:bg-brandBlue/80 text-sm px-4 py-2 rounded transition">עדכן מיפוי CoreMap™</button>\n                </form>\n            </div>\n\n            <!-- Questionnaires List -->\n            <div class="bg-black/30 border border-brandBlue/20 p-6 rounded-xl">\n                <h2 class="text-xl font-bold text-white mb-4 flex items-center gap-2">\n                    <span class="w-2.5 h-2.5 rounded-full bg-brandGreen"></span> שאלוני Pulse ושליחה\n                </h2>\n                {% if not active_functions %}\n                <p class="text-slate-400 text-sm">אנא בחר פונקציות ב-CoreMap™ למעלה כדי להפיק שאלוני אבחון.</p>\n                {% else %}\n                <div class="flex flex-col gap-4">\n                    {% for q in questionnaires %}\n                    <div class="flex flex-col sm:flex-row justify-between items-start sm:items-center p-4 bg-brandDark border border-brandBlue/10 rounded-lg gap-3">\n                        <div>\n                            <span class="text-xs font-semibold px-2 py-1 rounded bg-brandBlue/20 text-brandBlue">{{ q.role }}</span>\n                            <span class="text-xs ml-2 {% if q.status == \'completed\' %}text-brandGreen{% else %}text-amber-500{% endif %}">\n                                • {% if q.status == \'completed\' %}הושלם{% else %}ממתין למענה{% endif %}\n                            </span>\n                        </div>\n                        <div class="flex items-center gap-2 w-full sm:w-auto">\n                            <input type="text" readonly value="{{ host_url }}/q/{{ q.token }}" class="bg-black/40 border border-brandBlue/20 rounded px-2 py-1 text-xs text-slate-300 w-full sm:w-64 select-all">\n                            <button onclick="navigator.clipboard.writeText(\'{{ host_url }}/q/{{ q.token }}\'); alert(\'הקישור הועתק לקליפבורד!\');" class="bg-brandBlue hover:bg-brandBlue/80 text-xs px-3 py-1 rounded transition text-white">העתק</button>\n                        </div>\n                    </div>\n                    {% endfor %}\n                </div>\n                {% endif %}\n            </div>\n\n            <!-- Focus Points generated by AI Engine -->\n            <div class="bg-black/30 border border-brandBlue/20 p-6 rounded-xl">\n                <h2 class="text-xl font-bold text-white mb-2 flex items-center gap-2">\n                    <span class="w-2.5 h-2.5 rounded-full bg-brandRed"></span> מנוע הניתוח - CoreHeuristic™\n                </h2>\n                <p class="text-slate-400 text-sm mb-6">מערכת ה-AI סרקה את תשובות ה-Pulse ומצאה מוקדי חסימה והזדמנויות. באפשרותך לאשר, לערוך או להוסיף מוקדים חדשים.</p>\n\n                <!-- New Focus Point Form -->\n                <form action="/client/{{ client.id }}/add_focus" method="POST" class="bg-brandDark/50 border border-brandBlue/10 p-4 rounded-lg mb-6 flex flex-col gap-3">\n                    <h3 class="text-sm font-semibold text-white">הוספת מוקד ידני חדש:</h3>\n                    <div class="grid grid-cols-1 sm:grid-cols-3 gap-3">\n                        <input type="text" name="title" placeholder="כותרת המוקד" required class="bg-brandDark border border-brandBlue/30 rounded px-3 py-1.5 text-xs text-white focus:outline-none focus:border-brandRed">\n                        <select name="type" class="bg-brandDark border border-brandBlue/30 rounded px-3 py-1.5 text-xs text-white">\n                            <option value="strategic">אסטרטגי (דורש החלטת ליבה)</option>\n                            <option value="tactical">טקטי (טיפול נקודתי / נוהל)</option>\n                        </select>\n                        <select name="confidence" class="bg-brandDark border border-brandBlue/30 rounded px-3 py-1.5 text-xs text-white">\n                            <option value="5">רמת ודאות: 5 (גבוהה מאוד)</option>\n                            <option value="4">רמת ודאות: 4</option>\n                            <option value="3">רמת ודאות: 3</option>\n                            <option value="2">רמת ודאות: 2</option>\n                            <option value="1">רמת ודאות: 1 (נמוכה)</option>\n                        </select>\n                    </div>\n                    <textarea name="description" placeholder="תיאור הבעיה / חסם / הזדמנות ועדויות תומכות" required class="bg-brandDark border border-brandBlue/30 rounded px-3 py-1.5 text-xs text-white h-16 focus:outline-none focus:border-brandRed"></textarea>\n                    <button type="submit" class="bg-brandRed hover:bg-brandRed/90 text-xs text-white py-1.5 rounded transition self-end px-4 font-semibold">הוסף מוקד</button>\n                </form>\n\n                <!-- Focus Points List -->\n                <div class="flex flex-col gap-4">\n                    {% for f in focus_points %}\n                    <div class="border {% if f.type == \'strategic\' %}border-brandRed/30 bg-brandRed/5{% else %}border-brandBlue/20 bg-brandDark/40{% endif %} p-4 rounded-lg flex flex-col gap-2">\n                        <div class="flex justify-between items-start">\n                            <div>\n                                <span class="text-xs font-semibold px-2 py-0.5 rounded {% if f.type == \'strategic\' %}bg-brandRed/20 text-brandRed{% else %}bg-brandBlue/20 text-brandBlue{% endif %}">\n                                    {% if f.type == \'strategic\' %}אסטרטגי{% else %}טקטי{% endif %}\n                                </span>\n                                <h3 class="text-base font-bold text-white mt-1">{{ f.title }}</h3>\n                            </div>\n                            <div class="text-right">\n                                <div class="text-xs text-slate-400">רמת ודאות: <span class="text-brandGreen font-bold">{{ f.confidence }}/5</span></div>\n                                <div class="text-[10px] text-slate-500 mt-0.5">מקור: {{ f.source }}</div>\n                            </div>\n                        </div>\n                        <p class="text-sm text-slate-300">{{ f.description }}</p>\n                        <div class="flex justify-end gap-2 mt-2">\n                            <form action="/client/{{ client.id }}/delete_focus/{{ f.id }}" method="POST">\n                                <button type="submit" class="text-xs text-slate-500 hover:text-brandRed transition">מחק מוקד 🗑️</button>\n                            </form>\n                        </div>\n                    </div>\n                    {% endfor %}\n                </div>\n            </div>\n        </div>\n\n        <!-- Sidebar Actions & Results -->\n        <div class="flex flex-col gap-8">\n            <!-- Active Sprint Session -->\n            <div class="bg-black/30 border border-brandBlue/20 p-6 rounded-xl">\n                <h2 class="text-xl font-bold text-white mb-4">ניהול ספרינט Live 📊</h2>\n                <p class="text-slate-400 text-sm mb-4">המערכת משתמשת בטכנולוגיית WebSockets כדי להציג את ההצבעות והממצאים ב-Realtime לכל ההנהלה דרך הניידים.</p>\n                <div class="flex flex-col gap-3">\n                    <a href="/live/present" target="_blank" class="bg-brandBlue hover:bg-brandBlue/80 text-white text-center font-semibold py-2 rounded-lg transition text-sm">\n                        פתח מסך מקרן לניהול דיון ←\n                    </a>\n                    <a href="/live/join" target="_blank" class="border border-brandBlue/40 text-brandGreen hover:bg-brandBlue/10 text-center font-semibold py-2 rounded-lg transition text-sm">\n                        קישור הצבעה למנהלים מהנייד 📱\n                    </a>\n                </div>\n            </div>\n\n            <!-- Decision Cards & Action -->\n            <div class="bg-black/30 border border-brandBlue/20 p-6 rounded-xl">\n                <h2 class="text-xl font-bold text-white mb-4">כרטיסי הכרעה וחלופות 🎴</h2>\n                <p class="text-slate-400 text-sm mb-4">רכז את חלופות הפעולה וגבש את החלטות הליבה (Top-1 to Top-3) ליישום מהיר.</p>\n                \n                <form action="/client/{{ client.id }}/add_decision" method="POST" class="flex flex-col gap-3">\n                    <div>\n                        <label class="block text-slate-400 text-xs mb-1">כותרת ההכרעה / המהלך</label>\n                        <input type="text" name="title" required placeholder="לדוגמא: נוהל אישור חריגים מכירות-תפעול" class="w-full bg-brandDark border border-brandBlue/30 rounded px-2.5 py-1.5 text-xs text-white">\n                    </div>\n                    <div>\n                        <label class="block text-slate-400 text-xs mb-1">תוצאה מצופה (Outcome)</label>\n                        <textarea name="outcome" required placeholder="הגדרת תוצאה עסקית ברורה" class="w-full bg-brandDark border border-brandBlue/30 rounded px-2.5 py-1.5 text-xs text-white h-12"></textarea>\n                    </div>\n                    <div>\n                        <label class="block text-slate-400 text-xs mb-1">תוכנית 30/60/90 (משימות, בעלים, לו"ז)</label>\n                        <textarea name="execution_plan" required placeholder="משימה 1 (בעלים, לו"ז) \nמשימה 2..." class="w-full bg-brandDark border border-brandBlue/30 rounded px-2.5 py-1.5 text-xs text-white h-20"></textarea>\n                    </div>\n                    <button type="submit" class="bg-brandRed hover:bg-brandRed/90 text-xs text-white font-semibold py-2 rounded transition mt-2">צור כרטיס החלטה</button>\n                </form>\n\n                <!-- Decision Cards List -->\n                <div class="flex flex-col gap-4 mt-6">\n                    {% for d in decision_cards %}\n                    <div class="bg-brandDark/60 border border-brandGreen/30 p-4 rounded-lg">\n                        <h3 class="text-sm font-bold text-brandGreen">{{ d.title }}</h3>\n                        <p class="text-xs text-slate-400 mt-1"><strong>תוצאה:</strong> {{ d.outcome }}</p>\n                        <p class="text-xs text-slate-300 mt-2 bg-black/30 p-2 rounded whitespace-pre-line">{{ d.execution_plan }}</p>\n                    </div>\n                    {% endfor %}\n                </div>\n            </div>\n        </div>\n    </div>\n</div>\n{% endblock %}', 'templates/dashboard.html': '{% extends "base.html" %}\n\n{% block title %}לוח בקרה - B-MRI CoreFocus™{% endblock %}\n\n{% block content %}\n<div class="flex flex-col gap-8">\n    <div class="flex justify-between items-center">\n        <div>\n            <h1 class="text-3xl font-bold text-white">ניהול לקוחות וספרינטים</h1>\n            <p class="text-slate-400 mt-1">מערכת דיגיטלית לזיקוק 1-3 החלטות ליבה להנהלות ומנכ"לים</p>\n        </div>\n        <button onclick="document.getElementById(\'newClientModal\').classList.remove(\'hidden\')" class="bg-brandRed hover:bg-brandRed/90 text-white font-semibold px-5 py-2.5 rounded-lg transition shadow-lg">\n            + פתיחת תיק לקוח חדש\n        </button>\n    </div>\n\n    <!-- Stats Grid -->\n    <div class="grid grid-cols-1 md:grid-cols-3 gap-6">\n        <div class="bg-brandBlue/10 border border-brandBlue/20 p-6 rounded-xl">\n            <h3 class="text-slate-400 text-sm font-medium">סך הכל לקוחות פעילים</h3>\n            <p class="text-4xl font-extrabold text-white mt-2">{{ clients|length }}</p>\n        </div>\n        <div class="bg-brandBlue/10 border border-brandBlue/20 p-6 rounded-xl">\n            <h3 class="text-slate-400 text-sm font-medium">שאלוני Pulse שהושלמו</h3>\n            <p class="text-4xl font-extrabold text-brandGreen mt-2">{{ total_completed_q }}</p>\n        </div>\n        <div class="bg-brandBlue/10 border border-brandBlue/20 p-6 rounded-xl">\n            <h3 class="text-slate-400 text-sm font-medium">החלטות ליבה שגובשו</h3>\n            <p class="text-4xl font-extrabold text-brandRed mt-2">{{ total_decisions }}</p>\n        </div>\n    </div>\n\n    <!-- Client Table -->\n    <div class="bg-black/30 border border-brandBlue/20 rounded-xl overflow-hidden">\n        <div class="px-6 py-4 border-b border-brandBlue/20 bg-black/10">\n            <h2 class="text-lg font-semibold text-white">תיקי לקוח קיימים</h2>\n        </div>\n        {% if not clients %}\n        <div class="p-8 text-center text-slate-400">\n            טרם נפתחו תיקי לקוח במערכת. לחץ על הכפתור למעלה כדי להתחיל ספרינט חדש.\n        </div>\n        {% else %}\n        <div class="overflow-x-auto">\n            <table class="w-full text-right text-sm">\n                <thead class="bg-black/40 text-slate-400 font-medium">\n                    <tr>\n                        <th class="px-6 py-3.5">שם החברה / הארגון</th>\n                        <th class="px-6 py-3.5">מגזר / תעשייה</th>\n                        <th class="px-6 py-3.5">תאריך פתיחה</th>\n                        <th class="px-6 py-3.5">פעולות</th>\n                    </tr>\n                </thead>\n                <tbody class="divide-y divide-brandBlue/10">\n                    {% for client in clients %}\n                    <tr class="hover:bg-brandBlue/5 transition">\n                        <td class="px-6 py-4 font-bold text-white">{{ client.name }}</td>\n                        <td class="px-6 py-4 text-slate-300">{{ client.industry }}</td>\n                        <td class="px-6 py-4 text-slate-400">{{ client.created_at[:10] }}</td>\n                        <td class="px-6 py-4">\n                            <a href="/client/{{ client.id }}" class="text-brandGreen hover:underline font-semibold">כניסה לתיק לקוח ←</a>\n                        </td>\n                    </tr>\n                    {% endfor %}\n                </tbody>\n            </table>\n        </div>\n        {% endif %}\n    </div>\n</div>\n\n<!-- Modal -->\n<div id="newClientModal" class="fixed inset-0 z-50 bg-black/80 flex items-center justify-center p-4 hidden">\n    <div class="bg-[#242424] border border-brandBlue/40 rounded-xl max-w-md w-full p-6 shadow-2xl">\n        <h2 class="text-xl font-bold text-white mb-4">פתיחת תיק לקוח CoreFocus™</h2>\n        <form action="/client/create" method="POST" class="flex flex-col gap-4">\n            <div>\n                <label class="block text-slate-400 text-xs mb-1">שם החברה / הלקוח *</label>\n                <input type="text" name="name" required class="w-full bg-brandDark border border-brandBlue/30 rounded px-3 py-2 text-white focus:outline-none focus:border-brandRed">\n            </div>\n            <div>\n                <label class="block text-slate-400 text-xs mb-1">תעשייה / מגזר פעילות</label>\n                <input type="text" name="industry" class="w-full bg-brandDark border border-brandBlue/30 rounded px-3 py-2 text-white focus:outline-none focus:border-brandRed">\n            </div>\n            <div class="flex justify-end gap-3 mt-4">\n                <button type="button" onclick="document.getElementById(\'newClientModal\').classList.add(\'hidden\')" class="px-4 py-2 border border-brandBlue/20 rounded hover:bg-white/5 text-slate-300 transition">ביטול</button>\n                <button type="submit" class="px-4 py-2 bg-brandRed rounded text-white font-semibold hover:bg-brandRed/90 transition">צור תיק</button>\n            </div>\n        </form>\n    </div>\n</div>\n{% endblock %}', 'templates/base.html': '<!DOCTYPE html>\n<html lang="he" dir="rtl">\n<head>\n    <meta charset="UTF-8">\n    <meta name="viewport" content="width=device-width, initial-scale=1.0">\n    <title>{% block title %}B-MRI CoreFocus™ Platform{% endblock %}</title>\n    <!-- Tailwind CSS -->\n    <script src="https://cdn.tailwindcss.com"></script>\n    <script>\n        tailwind.config = {\n            theme: {\n                extend: {\n                    colors: {\n                        brandDark: \'#1A1A1A\',\n                        brandBlue: \'#3A5268\',\n                        brandRed: \'#E63946\',\n                        brandGreen: \'#A8D92E\',\n                        bgSlate: \'#0F172A\',\n                    },\n                    fontFamily: {\n                        sans: [\'Segoe UI\', \'system-ui\', \'sans-serif\'],\n                    }\n                }\n            }\n        }\n    </script>\n    <style>\n        body {\n            background-color: #1A1A1A;\n            color: #F8FAFC;\n        }\n    </style>\n    {% block head %}{% endblock %}\n</head>\n<body class="font-sans flex flex-col min-h-screen">\n    <!-- Header -->\n    <header class="bg-black/40 border-b border-brandBlue/30 backdrop-blur-md sticky top-0 z-50">\n        <div class="max-width-7xl mx-auto px-4 sm:px-6 lg:px-8 py-4 flex justify-between items-center">\n            <div class="flex items-center gap-3">\n                <!-- Visual Identity Anchor -->\n                <div class="flex items-center gap-1.5">\n                    <span class="w-3 h-3 rounded-full bg-brandRed"></span>\n                    <span class="w-12 h-[2px] bg-brandBlue"></span>\n                    <span class="w-3 h-3 rounded-full bg-brandGreen"></span>\n                </div>\n                <span class="text-xl font-bold tracking-wider text-white">B-MRI <span class="text-brandBlue">CoreFocus™</span></span>\n            </div>\n            <nav class="flex gap-6 text-sm font-medium text-slate-300">\n                <a href="/dashboard" class="hover:text-brandGreen transition">דשבורד לקוחות</a>\n                <a href="/live/present" class="hover:text-brandGreen transition" target="_blank">מצגת ספרינט Live</a>\n            </nav>\n        </div>\n    </header>\n\n    <!-- Main Content -->\n    <main class="flex-grow max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-8">\n        {% block content %}{% endblock %}\n    </main>\n\n    <!-- Footer -->\n    <footer class="bg-black/60 border-t border-brandBlue/20 py-6 text-center text-xs text-slate-500">\n        <p>© 2026 B-MRI. לזהות • לזקק • להכריע. כל הזכויות שמורות.</p>\n    </footer>\n</body>\n</html>'}

print("Starting extraction of B-MRI CoreFocus™ Platform...")

for filepath, content in FILES.items():
    # Create parent directories if they don't exist
    parent_dir = os.path.dirname(filepath)
    if parent_dir:
        os.makedirs(parent_dir, exist_ok=True)
        
    with open(filepath, "w", encoding="utf-8") as f:
        f.write(content)
    print(f"Created file: {filepath}")

